//! `pycompat::json` against CPython 3.12 and node (plan F2).
//!
//! - `golden/json.jsonl` is written by `port/difftest/oracle/json.py --golden` (fixed seeds) and
//!   regenerated by CI, so every line is what CPython printed (with the D-1 and D-6 divergences
//!   the oracle marks). Replaying it needs no Python.
//! - `js_stringify` is compared with node's `JSON.stringify(JSON.parse(text))` on the same texts
//!   when `node` is on `PATH`.
//! - Depth, linearity and round-trip properties.

use std::collections::{BTreeMap, HashSet};
use std::io::Write;
use std::process::{Command, Stdio};
use std::time::{Duration, Instant};

use anthology_pycompat::json::{
    COMPACT_SORTED, DumpOpts, INDENT2_SORTED, Int, JsonError, Map, PRESETS, PY_DEFAULT, Value,
    dumps, js_stringify, loads, loads_bytes_lossy, loads_utf8_sig,
};
use proptest::prelude::*;
use proptest::test_runner::{Config, RngSeed};

const GOLDEN: &str = concat!(env!("CARGO_MANIFEST_DIR"), "/tests/golden/json.jsonl");

fn golden() -> Vec<Value> {
    let text = std::fs::read_to_string(GOLDEN).expect("the golden corpus");
    text.lines()
        .enumerate()
        .map(|(i, line)| loads(line).unwrap_or_else(|e| panic!("golden line {}: {e}", i + 1)))
        .collect()
}

fn field<'a>(m: &'a Value, k: &str) -> &'a Value {
    m.as_object()
        .and_then(|o| o.get(k))
        .unwrap_or_else(|| panic!("no {k:?}"))
}

fn text_field<'a>(m: &'a Value, k: &str) -> &'a str {
    field(m, k)
        .as_str()
        .unwrap_or_else(|| panic!("{k:?} is not a string"))
}

fn preset(name: &str) -> DumpOpts {
    PRESETS
        .iter()
        .find(|(n, _)| *n == name)
        .unwrap_or_else(|| panic!("no preset {name}"))
        .1
}

fn unhex(s: &str) -> Vec<u8> {
    (0..s.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&s[i..i + 2], 16).expect("hex"))
        .collect()
}

fn fnv1a64(s: &str) -> String {
    let mut h: u64 = 0xcbf2_9ce4_8422_2325;
    for &b in s.as_bytes() {
        h = (h ^ u64::from(b)).wrapping_mul(0x0000_0100_0000_01b3);
    }
    format!("{h:016x}")
}

/// The text `json.loads` saw for a case, and Rust's result for it.
fn decode(case: &Value) -> (String, Result<Value, JsonError>) {
    match text_field(case, "op") {
        "loads_dumps" => {
            let text = text_field(case, "text");
            (text.to_string(), loads(text))
        }
        "loads_bytes_lossy" => {
            let b = unhex(text_field(case, "hex"));
            (
                String::from_utf8_lossy(&b).into_owned(),
                loads_bytes_lossy(&b),
            )
        }
        "loads_utf8_sig" => {
            let b = unhex(text_field(case, "hex"));
            let doc = std::str::from_utf8(&b)
                .map(|t| t.strip_prefix('\u{feff}').unwrap_or(t).to_string())
                .unwrap_or_default();
            (doc, loads_utf8_sig(&b))
        }
        op => panic!("unknown op {op}"),
    }
}

/// `(exit, stdout, stderr)` in the oracle's form.
fn run_case(case: &Value) -> (i64, String, String) {
    let (doc, result) = decode(case);
    match result {
        Ok(v) => (
            0,
            dumps(&v, &preset(text_field(case, "preset"))),
            String::new(),
        ),
        Err(e) => (
            1,
            String::new(),
            format!("{}: {}", e.type_name(), e.py_str(&doc)),
        ),
    }
}

fn short(s: &str) -> String {
    let cut: String = s.chars().take(160).collect();
    if cut.len() < s.len() {
        format!("{cut}…")
    } else {
        cut
    }
}

#[test]
fn the_golden_corpus_from_cpython_replays_exactly() {
    let lines = golden();
    assert!(lines.len() > 3000, "the corpus has {} lines", lines.len());
    let mut failures = Vec::new();
    let mut seen: BTreeMap<String, usize> = BTreeMap::new();
    for (i, line) in lines.iter().enumerate() {
        let case = field(line, "case");
        let want = field(line, "result");
        let (exit, stdout, stderr) = run_case(case);
        let want_exit = field(want, "exit").as_i64().expect("exit");
        let stdout_ok = match want.as_object().and_then(|o| o.get("stdout")) {
            Some(s) => s.as_str() == Some(stdout.as_str()),
            None => {
                let len = field(want, "stdout_len").as_i64().expect("stdout_len");
                usize::try_from(len).ok() == Some(stdout.chars().count())
                    && text_field(want, "stdout_fnv1a64") == fnv1a64(&stdout)
            }
        };
        if exit != want_exit || !stdout_ok || stderr != text_field(want, "stderr") {
            failures.push(format!(
                "line {}: {}\n  want exit {want_exit} {:?} {:?}\n  got  exit {exit} {:?} {:?}",
                i + 1,
                short(&dumps(case, &PY_DEFAULT)),
                short(
                    want.as_object()
                        .and_then(|o| o.get("stdout"))
                        .and_then(Value::as_str)
                        .unwrap_or("<hashed>")
                ),
                text_field(want, "stderr"),
                short(&stdout),
                stderr,
            ));
        }
        for tag in [
            format!("op {}", text_field(case, "op")),
            format!("preset {}", text_field(case, "preset")),
            format!("exit {want_exit}"),
        ] {
            *seen.entry(tag).or_default() += 1;
        }
        if let Some(d) = want.as_object().and_then(|o| o.get("divergence")) {
            *seen
                .entry(format!("divergence {}", d.as_str().unwrap_or("?")))
                .or_default() += 1;
        }
        if let Some(kind) = stderr.split(':').next().filter(|_| exit == 1) {
            *seen.entry(format!("error {kind}")).or_default() += 1;
        }
    }
    assert!(
        failures.is_empty(),
        "{} of {} golden cases differ:\n{}",
        failures.len(),
        lines.len(),
        failures
            .iter()
            .take(15)
            .cloned()
            .collect::<Vec<_>>()
            .join("\n")
    );
    // The corpus covers every op, preset, divergence and error class.
    for (name, _) in PRESETS {
        assert!(seen.contains_key(&format!("preset {name}")), "{seen:?}");
    }
    for tag in [
        "op loads_dumps",
        "op loads_bytes_lossy",
        "op loads_utf8_sig",
        "divergence D-1",
        "divergence D-6",
        "error JSONDecodeError",
        "error UnicodeDecodeError",
        "error ValueError",
    ] {
        assert!(seen.contains_key(tag), "no {tag}: {seen:?}");
    }
}

/// node: `JSON.stringify(JSON.parse(text))` per input line (a JSON string holding the text).
/// Lone surrogates become U+FFFD first (D-6), rebuilding objects so key order is kept; a text
/// where two such keys then collide reports `collision` (JavaScript has already merged them in
/// a different order than a decode-time replacement would).
const NODE_SCRIPT: &str = r#"
const fix = (s) => s.replace(/[\ud800-\udbff](?![\udc00-\udfff])|(?<![\ud800-\udbff])[\udc00-\udfff]/g, "�");
function sanitize(root) {
  let collision = false;
  const holder = { v: root };
  const stack = [[holder, "v"]];
  while (stack.length) {
    const [parent, key] = stack.pop();
    const v = parent[key];
    if (typeof v === "string") {
      parent[key] = fix(v);
    } else if (Array.isArray(v)) {
      for (let i = 0; i < v.length; i++) stack.push([v, i]);
    } else if (v !== null && typeof v === "object") {
      const out = Object.create(null);
      const seen = new Set();
      for (const k of Object.keys(v)) {
        const fk = fix(k);
        if (seen.has(fk)) collision = true;
        seen.add(fk);
        out[fk] = v[k];
      }
      parent[key] = out;
      for (const k of Object.keys(out)) stack.push([out, k]);
    }
  }
  return [holder.v, collision];
}
const out = [];
for (const line of require("fs").readFileSync(0, "utf8").split("\n")) {
  if (!line) continue;
  const text = JSON.parse(line);
  try {
    let v = JSON.parse(text);
    let collision = false;
    if (/\\u[dD][89a-fA-F]/.test(text)) [v, collision] = sanitize(v);
    out.push(JSON.stringify(collision ? { collision: true } : { ok: JSON.stringify(v) }));
  } catch (e) {
    out.push(JSON.stringify({ error: e.name }));
  }
}
process.stdout.write(out.join("\n") + "\n");
"#;

#[test]
fn js_stringify_matches_node_on_the_golden_texts() {
    if Command::new("node").arg("--version").output().is_err() {
        eprintln!("note: node is not on PATH; js_stringify was not compared with node");
        return;
    }
    let mut texts = Vec::new();
    let mut seen = HashSet::new();
    for line in golden() {
        let case = field(&line, "case");
        if text_field(case, "op") == "loads_utf8_sig" {
            continue;
        }
        let (text, value) = decode(case);
        if let Ok(v) = value
            && seen.insert(text.clone())
        {
            texts.push((text, v));
        }
    }
    let input: String = texts
        .iter()
        .map(|(t, _)| dumps(&Value::Str(t.clone()), &PY_DEFAULT) + "\n")
        .collect();
    let mut child = Command::new("node")
        .args(["--stack-size=65500", "-e", NODE_SCRIPT])
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .spawn()
        .expect("node runs");
    let mut stdin = child.stdin.take().expect("stdin");
    let writer = std::thread::spawn(move || stdin.write_all(input.as_bytes()));
    let output = child.wait_with_output().expect("node output");
    writer.join().expect("writer").expect("write to node");
    assert!(output.status.success(), "node failed: {output:?}");
    let stdout = String::from_utf8(output.stdout).expect("utf-8");
    let results: Vec<&str> = stdout.lines().collect();
    assert_eq!(results.len(), texts.len());
    let (mut compared, mut collisions, mut rejected) = (0, 0, 0);
    let mut failures = Vec::new();
    for ((text, value), result) in texts.iter().zip(results) {
        let result = loads(result).expect("node line");
        if let Some(ok) = result.as_object().and_then(|o| o.get("ok")) {
            compared += 1;
            let got = js_stringify(value);
            if ok.as_str() != Some(got.as_str()) {
                failures.push(format!(
                    "{}\n  node {}\n  rust {}",
                    short(text),
                    short(ok.as_str().unwrap_or("")),
                    short(&got)
                ));
            }
        } else if result
            .as_object()
            .and_then(|o| o.get("collision"))
            .is_some()
        {
            collisions += 1;
        } else {
            // JSON.parse rejects only the Python extensions NaN and ±Infinity.
            rejected += 1;
            assert!(
                text.contains("NaN") || text.contains("Infinity"),
                "node rejected {}: {}",
                short(text),
                dumps(&result, &PY_DEFAULT)
            );
        }
    }
    eprintln!(
        "node: {compared} compared, {collisions} D-6 key collisions, {rejected} NaN/Infinity"
    );
    assert!(
        failures.is_empty(),
        "{} of {compared} differ from node:\n{}",
        failures.len(),
        failures
            .iter()
            .take(15)
            .cloned()
            .collect::<Vec<_>>()
            .join("\n")
    );
    assert!(compared > 1400, "only {compared} texts compared");
}

/// Runs `f` on a thread with a 2 MiB stack (the default test thread size, made explicit).
fn on_small_stack(f: impl FnOnce() + Send + 'static) {
    std::thread::Builder::new()
        .stack_size(2 << 20)
        .spawn(f)
        .expect("thread")
        .join()
        .expect("no stack overflow or panic");
}

fn deep_round_trip(open: &str, leaf: &str, close: &str, depth: usize) {
    let text = format!("{}{leaf}{}", open.repeat(depth), close.repeat(depth));
    let v = loads(&text).expect("deep text parses");
    assert_eq!(dumps(&v, &PY_DEFAULT), text);
    let compact = text.replace(": ", ":");
    assert_eq!(dumps(&v, &COMPACT_SORTED), compact);
    assert_eq!(js_stringify(&v), compact);
    let c = v.clone();
    assert!(c == v);
    drop(c);
    let w = loads_bytes_lossy(text.as_bytes()).expect("bytes");
    assert!(w == v);
    drop(w);
    drop(v);
}

#[test]
fn depth_one_million_arrays_on_a_small_stack() {
    on_small_stack(|| deep_round_trip("[", "", "]", 1_000_000));
}

#[test]
fn depth_one_million_objects_on_a_small_stack() {
    on_small_stack(|| deep_round_trip("{\"a\": ", "1", "}", 1_000_000));
}

#[test]
fn depth_one_million_mixed_on_a_small_stack() {
    on_small_stack(|| deep_round_trip("[{\"k\": ", "\"x\"", "}]", 500_000));
}

#[test]
fn deep_errors_and_built_values_on_a_small_stack() {
    on_small_stack(|| {
        let d = 1_000_000;
        let e = loads(&"[".repeat(d)).unwrap_err();
        assert_eq!((e.msg.as_str(), e.pos), ("Expecting value", d));
        let e = loads(&"{\"a\":".repeat(d)).unwrap_err();
        assert_eq!((e.msg.as_str(), e.pos), ("Expecting value", 5 * d));
        // A value built by hand, not by `loads`, drops and compares iteratively too.
        let mut v = Value::Null;
        for i in 0..d {
            if i % 2 == 0 {
                v = Value::Array(vec![v, Value::Int(Int::Small(1))]);
            } else {
                let mut m = Map::new();
                m.insert("k".into(), v);
                v = Value::Object(m);
            }
        }
        let c = v.clone();
        assert!(c == v);
        let indented = dumps(&loads("[[[[1]]]]").expect("parses"), &INDENT2_SORTED);
        assert_eq!(
            indented,
            "[\n  [\n    [\n      [\n        1\n      ]\n    ]\n  ]\n]"
        );
    });
}

/// A named operation timed on a JSON text.
type Check<'a> = (&'a str, &'a dyn Fn(&str));

/// The fastest of three runs.
fn fastest(mut f: impl FnMut()) -> Duration {
    (0..3)
        .map(|_| {
            let t = Instant::now();
            f();
            t.elapsed()
        })
        .min()
        .unwrap_or_default()
}

/// Ten times the input must take well under a hundred times the time (quadratic). Ratios, not
/// absolutes, so debug builds and busy machines pass.
fn assert_linear(what: &str, small: &str, big: &str) {
    let ratio_of = |f: &dyn Fn(&str)| {
        let a = fastest(|| f(small)).as_secs_f64().max(1e-3);
        let b = fastest(|| f(big)).as_secs_f64();
        b / a
    };
    let checks: [Check<'_>; 5] = [
        ("loads", &|t| drop(loads(t).expect("parses"))),
        ("dumps", &|t| {
            drop(dumps(&loads(t).expect("parses"), &PY_DEFAULT))
        }),
        ("dumps sorted", &|t| {
            drop(dumps(&loads(t).expect("parses"), &INDENT2_SORTED))
        }),
        ("js_stringify", &|t| {
            drop(js_stringify(&loads(t).expect("parses")))
        }),
        ("clone and eq", &|t| {
            let v = loads(t).expect("parses");
            assert!(v.clone() == v);
        }),
    ];
    for (name, f) in checks {
        let ratio = ratio_of(f);
        assert!(
            ratio < 30.0,
            "{what}: {name} took {ratio:.1}x the time on 10x the input"
        );
    }
}

fn flat_doc(bytes: usize) -> String {
    let item = r#"{"k": 12345, "s": "abcé\n😀", "f": 1.5e-3, "b": [true, null], "n": -7}"#;
    let mut s = String::from("[");
    while s.len() < bytes {
        s.push_str(item);
        s.push_str(", ");
    }
    s.push_str("0]");
    s
}

fn many_keys_doc(keys: usize) -> String {
    let mut s = String::from("{");
    for i in 0..keys {
        // Every fourth key repeats an earlier one: the last value wins, in the first position.
        let k = if i % 4 == 3 { i - 2 } else { i };
        s.push_str(&format!("\"key{k}\": {i}, "));
    }
    s.push_str("\"end\": 0}");
    s
}

#[test]
fn ten_megabytes_flat_is_linear() {
    let big = flat_doc(10 << 20);
    assert!(big.len() >= 10 << 20);
    assert_linear("flat", &flat_doc(1 << 20), &big);
}

#[test]
fn half_a_million_keys_with_repeats_is_linear() {
    let big = many_keys_doc(500_000);
    assert!(big.len() >= 9 << 20, "{}", big.len());
    let v = loads(&big).expect("parses");
    let m = v.as_object().expect("object");
    assert_eq!(m.len(), 375_001);
    assert_eq!(m.get("key1").and_then(Value::as_i64), Some(3));
    assert_eq!(m.iter().nth(1).map(|(k, _)| k), Some("key1"));
    assert_linear("many keys", &many_keys_doc(50_000), &big);
}

#[test]
fn depth_one_hundred_thousand_is_linear() {
    let nest = |d: usize| format!("{}1{}", "[{\"a\": ".repeat(d), "}]".repeat(d));
    let checks: [Check<'_>; 4] = [
        ("loads", &|t| drop(loads(t).expect("parses"))),
        ("dumps", &|t| {
            drop(dumps(&loads(t).expect("parses"), &COMPACT_SORTED))
        }),
        ("js_stringify", &|t| {
            drop(js_stringify(&loads(t).expect("parses")))
        }),
        ("clone and eq", &|t| {
            let v = loads(t).expect("parses");
            assert!(v.clone() == v);
        }),
    ];
    let (small, big) = (nest(10_000), nest(100_000));
    for (name, f) in checks {
        let a = fastest(|| f(&small)).as_secs_f64().max(1e-3);
        let ratio = fastest(|| f(&big)).as_secs_f64() / a;
        assert!(
            ratio < 30.0,
            "depth: {name} took {ratio:.1}x the time on 10x the depth"
        );
    }
}

fn arb_string() -> impl Strategy<Value = String> {
    prop::collection::vec(any::<char>(), 0..10).prop_map(|cs| cs.into_iter().collect())
}

fn arb_value() -> impl Strategy<Value = Value> {
    let leaf = prop_oneof![
        Just(Value::Null),
        any::<bool>().prop_map(Value::Bool),
        any::<i64>().prop_map(|i| Value::Int(Int::Small(i))),
        (
            1u8..10,
            prop::collection::vec(0u8..10, 19..40),
            any::<bool>()
        )
            .prop_map(|(h, t, neg)| {
                let digits: String = std::iter::once(h)
                    .chain(t)
                    .map(|d| char::from(b'0' + d))
                    .collect();
                Value::Int(Int::Big(if neg { format!("-{digits}") } else { digits }))
            }),
        any::<f64>()
            .prop_filter("finite", |f| f.is_finite())
            .prop_map(Value::Float),
        arb_string().prop_map(Value::Str),
    ];
    leaf.prop_recursive(5, 96, 8, |inner| {
        prop_oneof![
            prop::collection::vec(inner.clone(), 0..8).prop_map(Value::Array),
            prop::collection::vec((arb_string(), inner), 0..8).prop_map(|kv| {
                let mut m = Map::new();
                for (k, v) in kv {
                    m.insert(k, v);
                }
                Value::Object(m)
            }),
        ]
    })
}

fn fixed_seed(cases: u32) -> Config {
    Config {
        cases,
        rng_seed: RngSeed::Fixed(20_261_120),
        failure_persistence: None,
        ..Config::default()
    }
}

proptest! {
    #![proptest_config(fixed_seed(512))]

    #[test]
    fn dumps_then_loads_gives_the_value_back_under_every_preset(v in arb_value()) {
        for (name, o) in PRESETS {
            let text = dumps(&v, &o);
            let back = loads(&text).map_err(|e| TestCaseError::fail(format!("{name}: {e}")))?;
            prop_assert!(back == v, "{name}: {text}");
            prop_assert_eq!(dumps(&back, &o), text);
        }
        let js = js_stringify(&v);
        prop_assert!(loads(&js).is_ok(), "{js}");
    }

    #[test]
    fn loads_never_panics_on_arbitrary_bytes(b in prop::collection::vec(any::<u8>(), 0..64)) {
        let _ = loads_bytes_lossy(&b);
        let _ = loads_utf8_sig(&b);
    }

    #[test]
    fn loads_never_panics_on_json_like_text(
        cs in prop::collection::vec(prop::sample::select(
            "[]{}:,\"\\ 0123456789eE.+-utrfalsnNI\u{e9}\u{1f600}\u{1}".chars().collect::<Vec<_>>()
        ), 0..40)
    ) {
        let text: String = cs.into_iter().collect();
        if let Ok(v) = loads(&text) {
            for (_, o) in PRESETS {
                let _ = dumps(&v, &o);
            }
            let _ = js_stringify(&v);
        }
    }
}
